package vn.eduassistant.backend.web;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import java.util.*;

@RestController
public class AuditController {
    private final AuthService auth;private final JdbcSupport db;
    public AuditController(AuthService auth,JdbcSupport db){this.auth=auth;this.db=db;}
    @GetMapping("/api/audits") public ResponseEntity<?> list(@RequestParam(required=false)String action,@RequestParam(required=false)String caseId,@RequestParam(required=false)String actorRole,@RequestParam(required=false)String date,@RequestParam(required=false)String dateFrom,@RequestParam(required=false)String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(defaultValue="false")boolean includeInput,HttpServletRequest request){Map<String,Object>u=auth.currentUser(request);StringBuilder where=new StringBuilder(" WHERE 1=1");List<Object>args=new ArrayList<Object>();if("STUDENT".equals(u.get("role"))){where.append(" AND (caseid IN (SELECT id FROM cases WHERE studentid=?) OR (caseid IS NULL AND actorid=?))");args.add(u.get("id"));args.add(u.get("id"));}else{if(action!=null&&!action.isEmpty()&&!"ALL".equals(action)){where.append(" AND action=?");args.add(action);}if(caseId!=null&&!caseId.isEmpty()){where.append(" AND caseid=?");args.add(caseId);}if(actorRole!=null&&!actorRole.isEmpty()&&!"ALL".equals(actorRole)){where.append(" AND actorrole=?");args.add(actorRole);}}if(date!=null&&!date.isEmpty()){where.append(" AND timestamp LIKE ?");args.add(date+"%");}if(dateFrom!=null&&!dateFrom.isEmpty()){where.append(" AND timestamp>=?");args.add(dateFrom+"T00:00:00");}if(search!=null&&!search.trim().isEmpty()){where.append(" AND (LOWER(action) LIKE ? OR LOWER(COALESCE(caseid,'')) LIKE ? OR LOWER(COALESCE(actorname,'')) LIKE ? OR LOWER(COALESCE(actorusername,'')) LIKE ? OR LOWER(COALESCE(reason,'')) LIKE ?)");String term="%"+search.trim().toLowerCase()+"%";for(int i=0;i<5;i++)args.add(term);}long total=db.count("SELECT COUNT(id) FROM audits"+where,args.toArray());int size=Math.max(10,Math.min(100,pageSize)),totalPages=Math.max(1,(int)Math.ceil(total/(double)size)),safePage=Math.max(1,Math.min(page,totalPages));String columns="id,action,caseid AS \"caseId\",actorid AS \"actorId\",actorname AS \"actorName\",actorrole AS \"actorRole\",actorusername AS \"actorUsername\","+(includeInput&&Arrays.asList("ADMIN","REVIEWER").contains(u.get("role"))?"inputdata AS \"inputData\",":"")+"result,reason,timestamp";List<Map<String,Object>> rows=db.all("SELECT "+columns+" FROM audits"+where+" ORDER BY timestamp DESC LIMIT ? OFFSET ?",append(args.toArray(),size,(safePage-1)*size));List<Map<String,Object>> output=new ArrayList<Map<String,Object>>();for(Map<String,Object>r:rows)output.add(formatAudit(r));return ApiResponse.success(200,"Lấy danh sách nhật ký kiểm toán thành công.",UserService.map("audits",output,"total",total,"page",safePage,"pageSize",size,"totalPages",totalPages,"hasPrevious",safePage>1,"hasNext",safePage<totalPages));}
    @GetMapping({"/api/audits/export-csv","/api/audits/export"}) public ResponseEntity<byte[]> export(HttpServletRequest request){auth.require(request,"REVIEWER","ADMIN");StringBuilder csv=new StringBuilder("\uFEFFTimestamp,Action,Case,Actor,Role,Result,Reason\r\n");for(Map<String,Object>r:db.all("SELECT * FROM audits ORDER BY timestamp DESC")){Object[]v={r.get("timestamp"),r.get("action"),r.get("caseId"),r.get("actorName"),r.get("actorRole"),r.get("result"),r.get("reason")};for(int i=0;i<v.length;i++){if(i>0)csv.append(',');csv.append('"').append(String.valueOf(v[i]==null?"":v[i]).replace("\"","\"\"")).append('"');}csv.append("\r\n");}HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.parseMediaType("text/csv; charset=UTF-8"));h.setContentDisposition(ContentDisposition.attachment().filename("EDUASSISTANT_Audit_Trail_"+System.currentTimeMillis()+".csv").build());return new ResponseEntity<byte[]>(csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),h,HttpStatus.OK);}
    private static Map<String,Object> formatAudit(Map<String,Object>r){Object input=Json.parse(Json.str(r.get("inputData")));if(input==null)input=Json.str(r.get("inputData"));return UserService.map("id",r.get("id"),"timestamp",r.get("timestamp"),"action",r.get("action"),"actor",UserService.map("id",r.get("actorId"),"name",r.get("actorName"),"role",r.get("actorRole"),"username",r.get("actorUsername")),"caseId",r.get("caseId"),"input",input,"result",r.get("result")==null?"SUCCESS":r.get("result"),"reason",r.get("reason"));}
    private static Object[] append(Object[]source,Object...extra){Object[]out=Arrays.copyOf(source,source.length+extra.length);System.arraycopy(extra,0,out,source.length,extra.length);return out;}
}
